insert into father_activities (id, category, month_postpartum, applies_to, title, description, duration_minutes, duration_label, time_of_day, with_baby, effort_level, next_step) values
  ('take-the-night-shift-m1', 'supporting_her_recovery'::father_activity_category, 1, 'all'::father_activity_relevance, 'Take the Night Shift', 'Pick a block of the night — say 9pm to 1am — where you are fully on duty and she sleeps without listening for the baby. If she''s breastfeeding, bring the baby to her, handle the nappy and the settling, take the baby back. Broken sleep is the single biggest driver of postpartum depression, and this is the most useful thing you can do in month one.', null, 'Ongoing', 'night'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 2: review the split as baby''s pattern changes. Month 4: adjust again.'),
  ('be-the-gatekeeper-m1', 'supporting_her_recovery'::father_activity_category, 1, 'all'::father_activity_relevance, 'Be the Gatekeeper', 'You handle the visitors. Who comes, when, for how long, and when they leave. She should never have to be the one saying no or feeling rude. Say it plainly: ''We''re keeping things quiet for a few weeks, we''ll let you know when we''re ready.'' This is a genuinely useful job and it costs her nothing.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: start letting in one or two people, on her terms not theirs.'),
  ('bring-food-and-water-unasked-m1', 'supporting_her_recovery'::father_activity_category, 1, 'all'::father_activity_relevance, 'Bring Food and Water, Unasked', 'She will forget to eat and drink, especially while feeding. Put water beside her every time she sits down. Bring food she can eat one-handed. Don''t ask if she wants anything — she''ll say no out of habit. Just bring it.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue all 12 months. It stops being urgent but never stops mattering.'),
  ('learn-what-her-recovery-involves-m1', 'supporting_her_recovery'::father_activity_category, 1, 'all'::father_activity_relevance, 'Learn What Her Recovery Involves', 'Read up on what actually happens to a body after birth — bleeding for weeks, afterpains, engorgement, hormone crashes, hair loss, night sweats. Most men know almost nothing about this and then find the reality alarming. Knowing what''s normal means you can be calm when she needs calm, and worried at the right moments.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: learn the warning signs that need a doctor. Month 3: learn about PPD specifically.'),
  ('watch-for-warning-signs-m1', 'supporting_her_recovery'::father_activity_category, 1, 'all'::father_activity_relevance, 'Watch for Warning Signs', 'Know the red flags: fever over 38°C, heavy bleeding soaking a pad an hour, foul-smelling discharge, severe headache, chest pain, calf pain or swelling, or thoughts of harming herself or the baby. She may not report these — exhausted people minimise. You are the second set of eyes. Any of these means calling the doctor today.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue throughout. Month 2: add mood warning signs to what you watch for.'),
  ('do-all-the-lifting-m1', 'supporting_her_recovery'::father_activity_category, 1, 'caesarean'::father_activity_relevance, 'Do All the Lifting', 'For six weeks she lifts nothing heavier than the baby. That means you carry everything — laundry baskets, shopping, the toddler, the car seat. This is the most-ignored surgical instruction and the most common cause of wound complications. Enforce it kindly and without making her ask.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 2: reassess at the six-week check before she lifts anything heavier.'),
  ('learn-the-wound-signs-m1', 'supporting_her_recovery'::father_activity_category, 1, 'caesarean'::father_activity_relevance, 'Learn the Wound Signs', 'Check the incision daily with her. Normal: bruising, numbness, itching. Not normal: spreading redness, warmth, swelling, discharge, a foul smell, separating edges, or fever above 38°C. Surgical wound infections escalate quickly and are far easier to treat early.', 10, '10 min', 'morning'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: wound should be closed. Watch for late infection anyway.'),
  ('help-her-out-of-bed-m1', 'supporting_her_recovery'::father_activity_category, 1, 'caesarean'::father_activity_relevance, 'Help Her Out of Bed', 'She can''t sit straight up — it loads the incision directly. She needs to roll to her side and push up sideways. In the first two weeks she''ll often need a hand doing it, especially at night. Learn the movement so you can help without pulling her wrong.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: she should manage independently. Keep helping at night if it''s easier.'),
  ('bring-the-baby-to-her-m1', 'supporting_her_recovery'::father_activity_category, 1, 'caesarean'::father_activity_relevance, 'Bring the Baby to Her', 'She physically cannot bend and lift the baby from a cot or the floor for weeks. Every feed, every pick-up, every settle in the early period needs you to bring the baby to her and take them back. Anticipate it rather than waiting to be called.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 2: she can lift the baby but not much more.'),
  ('keep-a-pillow-everywhere-m1', 'supporting_her_recovery'::father_activity_category, 1, 'caesarean'::father_activity_relevance, 'Keep a Pillow Everywhere', 'She needs to hold a firm pillow against the incision whenever she coughs, sneezes or laughs. Put one wherever she sits — sofa, bed, car, feeding chair. Unsupported coughing in the early weeks genuinely hurts and strains the wound.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: still useful during a cold or a laughing fit.'),
  ('take-over-driving-m1', 'supporting_her_recovery'::father_activity_category, 1, 'caesarean'::father_activity_relevance, 'Take Over Driving', 'She shouldn''t drive for around six weeks — emergency braking loads the incision and insurance often won''t cover it. Plan the logistics so she isn''t stranded or tempted, and so appointments don''t become a problem.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: confirm with the doctor before she resumes.'),
  ('do-the-first-nappy-m1', 'bonding_with_baby'::father_activity_category, 1, 'all'::father_activity_relevance, 'Do the First Nappy', 'Change the first nappy, and then keep changing them. Nappies, baths, burping, settling — these are the tasks where fathers most often defer to the mother and then never catch up in confidence. Start on day one, be bad at it, get better.', 5, '5 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: you should be as fast as her. Month 3: take over bathtime entirely.'),
  ('skin-to-skin-yours-too-m1', 'bonding_with_baby'::father_activity_category, 1, 'all'::father_activity_relevance, 'Skin-to-Skin, Yours Too', 'Bare chest, baby on you, a blanket over both. Skin-to-skin isn''t only a mother thing — it regulates the baby''s temperature and heart rate and floods you with oxytocin too. Fathers who do this early report feeling connected to their baby much sooner.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue every month. Month 6: still works, even as they get wriggly.'),
  ('talk-to-your-baby-m1', 'bonding_with_baby'::father_activity_category, 1, 'all'::father_activity_relevance, 'Talk to Your Baby', 'Your voice is lower than hers, and babies find it distinctive and calming. Talk while you change them, carry them, walk with them. It doesn''t matter what you say — cricket scores, what you''re cooking, what you''re worried about. The sound is the point.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 3: they''ll turn toward your voice. Month 6: they''ll respond with sounds back.'),
  ('find-your-own-hold-m1', 'bonding_with_baby'::father_activity_category, 1, 'all'::father_activity_relevance, 'Find Your Own Hold', 'Every parent settles a baby differently. Find the hold that works for you — over the shoulder, along the forearm, chest to chest — rather than copying hers exactly. Babies learn to be soothed in more than one way, and having your own method means she isn''t the only one who can settle them.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: your hold should work reliably. Month 4: you become the settling expert for one part of the day.'),
  ('name-what-you-re-feeling-m1', 'your_own_wellbeing'::father_activity_category, 1, 'all'::father_activity_relevance, 'Name What You''re Feeling', 'Fathers often feel useless, sidelined, terrified, or numb in month one and rarely say so. Say it to someone — a friend, a brother, her. Naming it stops it turning into distance or irritability. You are allowed to be finding this hard.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 3: check in with yourself again. Month 6: paternal PPD screening.'),
  ('sleep-when-you-can-m1', 'your_own_wellbeing'::father_activity_category, 1, 'all'::father_activity_relevance, 'Sleep When You Can', 'You will be tempted to run on empty and prove something. Don''t. A father who is functioning is worth more than a father who is heroic and then falls apart in month three. Take the naps. Accept the help offered to you too.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue throughout. Month 6: audit your own sleep debt the way she does hers.'),
  ('take-over-the-invisible-work-m1', 'practical_load'::father_activity_category, 1, 'all'::father_activity_relevance, 'Take Over the Invisible Work', 'The invisible work is remembering the vaccination date, noticing the nappies are running out, knowing which vest is clean. Don''t wait to be asked and don''t ask ''what do you need me to do'' — that still makes her the manager. Pick two whole areas and own them completely.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 3: own four areas. Month 6: the mental load should be genuinely shared.'),
  ('set-up-the-feeding-station-m1', 'practical_load'::father_activity_category, 1, 'all'::father_activity_relevance, 'Set Up the Feeding Station', 'Wherever she feeds most, set it up properly: water, snacks, phone charger, muslins, nappies, a cushion, the TV remote. She may sit there for hours a day. Making that spot work well is a small act with an outsized return.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 3: rebuild it as feeding patterns change.'),
  ('say-the-thing-out-loud-m1', 'couple_relationship'::father_activity_category, 1, 'all'::father_activity_relevance, 'Say the Thing Out Loud', 'Once this week, tell her plainly what you saw her do. ''You fed him for forty minutes at three in the morning and you didn''t complain once.'' Not praise for being a good mother in the abstract — one specific thing you actually witnessed. She is likely to feel invisible right now.', 5, '5 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue every month. Month 4: she does the same for you.'),
  ('two-minutes-not-about-the-baby-m1', 'couple_relationship'::father_activity_category, 1, 'all'::father_activity_relevance, 'Two Minutes, Not About the Baby', 'Once a day, ask her one question that has nothing to do with the baby, and mean it. Two minutes. In month one that is the whole relationship maintenance plan, and it''s enough.', 4, '4 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: extend to five minutes with a high and a hard each.'),
  ('notice-what-changed-for-you-m1', 'becoming_a_father'::father_activity_category, 1, 'all'::father_activity_relevance, 'Notice What Changed for You', 'Write or think through: what has actually changed for me? Not what should have changed — what has. Freedom, sleep, identity, how people treat me, what I worry about. Fathers rarely get asked this and it goes unexamined for years.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: revisit. Month 12: full year reflection.'),
  ('tell-work-early-m1', 'becoming_a_father'::father_activity_category, 1, 'all'::father_activity_relevance, 'Tell Work Early', 'Have the conversation with your employer about what the next few months look like — leave, flexibility, hours. Fathers who negotiate this early get better outcomes than those who improvise week by week and slowly disappoint everyone.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 3: review whether the arrangement is actually working.'),
  ('go-to-the-6-week-check-m2', 'supporting_her_recovery'::father_activity_category, 2, 'all'::father_activity_relevance, 'Go to the 6-Week Check', 'Go with her. Take notes. She''s exhausted and may not absorb or ask everything. You can ask the questions she''s too tired to raise, and hearing the answers directly means you''re not relying on a secondhand account of her own body.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 3: follow through on anything the doctor recommended, especially physio referrals.'),
  ('learn-the-mood-warning-signs-m2', 'supporting_her_recovery'::father_activity_category, 2, 'all'::father_activity_relevance, 'Learn the Mood Warning Signs', 'Postpartum depression looks like persistent low mood, loss of interest, hopelessness, difficulty bonding, rage, or constant anxiety lasting more than two weeks. It is not the same as baby blues. If you see it, say so gently and directly, and go with her to the doctor. Many women won''t raise it themselves.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 4: PPD often peaks around 3-4 months. Stay alert then especially.'),
  ('protect-her-nap-m2', 'supporting_her_recovery'::father_activity_category, 2, 'all'::father_activity_relevance, 'Protect Her Nap', 'When she sleeps in the day, the house is yours and so is the baby. No waking her to ask where something is. This is the single most valuable two hours you can give her and it''s easy to accidentally erode.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue throughout. Month 6: she should be able to nap without any negotiation.'),
  ('understand-the-slower-timeline-m2', 'supporting_her_recovery'::father_activity_category, 2, 'caesarean'::father_activity_relevance, 'Understand the Slower Timeline', 'C-section recovery genuinely takes longer, and she may compare herself unfavourably to friends who delivered vaginally. Six weeks is not healed — it''s cleared. The abdominal wall keeps remodelling for a year or more. Say this out loud to her; it lands better from you than from the internet.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: still true. Month 12: still remodelling.'),
  ('take-bathtime-m2', 'bonding_with_baby'::father_activity_category, 2, 'all'::father_activity_relevance, 'Take Bathtime', 'Own bathtime completely — the running of the bath, the washing, the drying, the dressing. A ritual that is reliably yours builds your confidence and gives her a predictable window off duty.', 20, '20 min', 'evening'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 4: extend it into the whole bedtime routine. Month 6: bath becomes play.'),
  ('mirror-their-face-m2', 'bonding_with_baby'::father_activity_category, 2, 'all'::father_activity_relevance, 'Mirror Their Face', 'Hold your baby about 25cm away and copy their expressions. Open your mouth when they do, stick your tongue out, widen your eyes. Around this age they start copying back. This is the first real conversation you''ll have with your child.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 3: they smile first and wait for your response. Month 4: back-and-forth sounds.'),
  ('wear-your-baby-m2', 'bonding_with_baby'::father_activity_category, 2, 'all'::father_activity_relevance, 'Wear Your Baby', 'Get a carrier and use it. Walk to the shops, do the washing up, take a phone call. It''s practical, it settles the baby, and it builds a physical closeness that doesn''t depend on feeding.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: switch to a hip or back carry as they get heavier.'),
  ('keep-one-thing-that-s-yours-m2', 'your_own_wellbeing'::father_activity_category, 2, 'all'::father_activity_relevance, 'Keep One Thing That''s Yours', 'One activity from before — football on Sunday, gym, a friend, a hobby. Not four hours. One thing, protected. Fathers who lose everything of their own tend to become resentful somewhere around month five, and it comes out sideways.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 4: make sure she has the equivalent. Month 6: both non-negotiable.'),
  ('talk-to-another-father-m2', 'your_own_wellbeing'::father_activity_category, 2, 'all'::father_activity_relevance, 'Talk to Another Father', 'Find one man who''s a year or two ahead and talk to him honestly. Not advice-swapping — just saying out loud what''s hard. Most fathers have no one they discuss this with, and the isolation is real even when nobody names it.', 45, '45 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: make it regular. Month 12: be that person for someone newer.'),
  ('own-the-admin-m2', 'practical_load'::father_activity_category, 2, 'all'::father_activity_relevance, 'Own the Admin', 'Birth registration, insurance, paediatrician appointments, vaccination schedule, bank and nominee updates. It''s tedious and it doesn''t require breastfeeding. Take all of it.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 4: own the calendar entirely. Month 6: she should never have to remember a date.'),
  ('cook-or-arrange-the-food-m2', 'practical_load'::father_activity_category, 2, 'all'::father_activity_relevance, 'Cook or Arrange the Food', 'Either you cook or you organise it — batch meals, a cook, a reliable rotation. ''We''ll order something'' every night stops being sustainable fast, and postpartum nutrition genuinely affects her recovery and milk supply.', 45, '45 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 4: build a repeatable weekly system rather than deciding daily.'),
  ('five-minutes-one-high-one-hard-m2', 'couple_relationship'::father_activity_category, 2, 'all'::father_activity_relevance, 'Five Minutes, One High One Hard', 'Extend the daily check-in. Each of you shares one good thing and one hard thing from the day. No fixing, no advice. Just listening. Five minutes, every night.', 5, '5 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 4: add one specific appreciation each.'),
  ('ask-what-she-actually-wants-m2', 'couple_relationship'::father_activity_category, 2, 'all'::father_activity_relevance, 'Ask What She Actually Wants', 'When she describes something difficult, ask: do you want me to help solve this, or do you want me to just listen? Getting this wrong is the most common source of pointless friction in the first year, and asking takes three seconds.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue throughout. Eventually you''ll know without asking.'),
  ('rethink-what-a-father-does-m2', 'becoming_a_father'::father_activity_category, 2, 'all'::father_activity_relevance, 'Rethink What a Father Does', 'Most Indian men grew up watching fathers who provided and were present, but weren''t hands-on in the daily way. That''s the template you inherited, and it isn''t a criticism of your father — it''s just what the era looked like. Decide deliberately what you want to do differently rather than defaulting.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: notice which of your own father''s habits you''ve picked up without choosing them.'),
  ('push-for-physio-if-she-needs-it-m3', 'supporting_her_recovery'::father_activity_category, 3, 'all'::father_activity_relevance, 'Push for Physio If She Needs It', 'If she has leaking, heaviness, back pain, painful intercourse, or a tummy gap, a women''s health physiotherapist treats all of it. Most women don''t go because they assume it''s normal, or they don''t want the fuss. Book it and go with her.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: follow up on whether the exercises are actually happening.'),
  ('give-her-a-real-break-m3', 'supporting_her_recovery'::father_activity_category, 3, 'all'::father_activity_relevance, 'Give Her a Real Break', 'Not an hour while you''re in the next room. Take the baby out for three hours and let her have the house to herself, or send her out with no return time. The mental load only lifts when she genuinely isn''t on call.', 180, '180 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: make it a weekly fixture, not a favour.'),
  ('learn-her-body-signals-m3', 'supporting_her_recovery'::father_activity_category, 3, 'all'::father_activity_relevance, 'Learn Her Body Signals', 'She will not always say she''s in pain or struggling. Learn her tells — the way she holds herself, goes quiet, gets short-tempered. Then name it gently: ''You seem like you''re in pain, what''s going on?'' Being seen without having to explain is a genuine relief.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue throughout.'),
  ('back-the-scar-massage-habit-m3', 'supporting_her_recovery'::father_activity_category, 3, 'caesarean'::father_activity_relevance, 'Back the Scar Massage Habit', 'Daily scar massage from around six weeks genuinely prevents the adhesions that cause pulling, restricted movement and back pain years later. It''s easy to skip because nothing hurts yet. Remind her without nagging, and take the baby so she has five uninterrupted minutes.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 8: should be habitual. Month 12: taper to maintenance.'),
  ('get-on-the-floor-m3', 'bonding_with_baby'::father_activity_category, 3, 'all'::father_activity_relevance, 'Get on the Floor', 'Tummy time works far better with a face at their level. Lie down opposite them, make noise, be interesting. This is also where you''ll notice their development happening — the day they push up higher, the day they roll.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 5: they''ll roll toward you. Month 7: they''ll crawl to you.'),
  ('take-over-one-full-routine-m3', 'bonding_with_baby'::father_activity_category, 3, 'all'::father_activity_relevance, 'Take Over One Full Routine', 'Pick one daily routine — morning wake-up, bedtime, the afternoon walk — and own it completely and consistently. Predictable presence from you builds a distinct relationship with your child that isn''t just backup for her.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: the baby should show clear anticipation when your routine starts.'),
  ('read-to-them-m3', 'bonding_with_baby'::father_activity_category, 3, 'all'::father_activity_relevance, 'Read to Them', 'Ten minutes, any book, every day. They''re not following the story — they''re absorbing your voice, rhythm and attention. Reading is one of the easiest fatherhood habits to start early and one of the hardest to start late.', 10, '10 min', 'evening'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: they''ll turn pages. Month 12: they''ll bring you the book.'),
  ('check-in-with-yourself-m3', 'your_own_wellbeing'::father_activity_category, 3, 'all'::father_activity_relevance, 'Check In With Yourself', 'Paternal depression is real and affects roughly one in ten fathers, usually peaking between three and six months. Signs: irritability, withdrawal, working late to avoid home, drinking more, feeling nothing. If any of this fits, talk to a doctor. It''s treatable and it''s more common than anyone admits.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: check again. This peaks later than most people expect.'),
  ('move-your-body-m3', 'your_own_wellbeing'::father_activity_category, 3, 'all'::father_activity_relevance, 'Move Your Body', 'Twenty minutes, three times a week, anything. Fathers gain weight and lose fitness in the first year at almost the same rate as mothers, but nobody tracks it or talks about it. Your energy directly affects how present you can be.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: build to a regular routine. Month 12: set a real fitness goal.'),
  ('run-the-house-for-a-weekend-m3', 'practical_load'::father_activity_category, 3, 'all'::father_activity_relevance, 'Run the House for a Weekend', 'Take a full weekend where you run everything — meals, cleaning, shopping, baby, laundry. Not as a demonstration. As a genuine test of whether you know how the household actually works. Most fathers discover several things they didn''t know were happening.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: it should feel routine rather than an event.'),
  ('have-the-real-conversation-m3', 'couple_relationship'::father_activity_category, 3, 'all'::father_activity_relevance, 'Have the Real Conversation', 'Twenty minutes, not at 11pm: how are we doing as a couple? Not logistics. What''s been hardest, what''s working, what each of you needs. Most couples haven''t had this conversation by month three and it shows.', 20, '20 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: make it a weekly 20-minute fixture.'),
  ('ask-about-intimacy-without-pressure-m3', 'couple_relationship'::father_activity_category, 3, 'all'::father_activity_relevance, 'Ask About Intimacy Without Pressure', 'Physical intimacy may or may not have restarted. Ask how she''s feeling about it, make clear there''s no expectation attached to the question, and listen. Not raising it at all reads as either indifference or pressure building. Raising it well is neither.', 15, '15 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: revisit. If pain is the issue, that''s physio-treatable, not permanent.'),
  ('define-the-father-you-want-to-be-m3', 'becoming_a_father'::father_activity_category, 3, 'all'::father_activity_relevance, 'Define the Father You Want to Be', 'Write down five things you want your child to say about you when they''re thirty. Then look at your last month honestly. The gap between the two is your actual to-do list, and it''s usually about time and attention rather than money.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: reread and reassess.'),
  ('watch-for-month-4-mood-dip-m4', 'supporting_her_recovery'::father_activity_category, 4, 'all'::father_activity_relevance, 'Watch for Month 4 Mood Dip', 'PPD peaks for many women around three to four months, right when everyone else has stopped asking. The visitors have gone, she may be back at work or facing it, and the exhaustion has accumulated. Ask her directly how she''s doing, and ask twice if the first answer is ''fine''.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: ask again. Month 9: ask again.'),
  ('back-her-return-to-work-m4', 'supporting_her_recovery'::father_activity_category, 4, 'all'::father_activity_relevance, 'Back Her Return to Work', 'If she''s returning, the logistics are not her problem alone. Childcare handover, sick-day cover, who does drop-off, whose meeting moves when the baby has a fever. Agree it now, in detail, rather than discovering the default is always her.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: review honestly whose career is absorbing the disruption.'),
  ('guard-her-exercise-time-m4', 'supporting_her_recovery'::father_activity_category, 4, 'all'::father_activity_relevance, 'Guard Her Exercise Time', 'She''s likely restarting physical activity. Guard that slot the way you''d guard a work meeting. It''s not leisure — it''s rehabilitation of a body that was structurally altered, and it''s the thing most easily lost to a fussy afternoon.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 8: should be automatic and never negotiated.'),
  ('know-about-the-numbness-m4', 'supporting_her_recovery'::father_activity_category, 4, 'caesarean'::father_activity_relevance, 'Know About the Numbness', 'Numbness above the scar is extremely common and nobody warns women about it. It can persist for a year or longer and it can feel distressing — like part of her body isn''t hers. It usually improves slowly. Knowing it''s expected makes it much less frightening.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: desensitisation work can help if it persists.'),
  ('play-the-anticipation-game-m4', 'bonding_with_baby'::father_activity_category, 4, 'all'::father_activity_relevance, 'Play the Anticipation Game', 'Do the same silly thing three times, then pause and wait. The grin before you do it the fourth time is anticipation — their brain predicting the future. Peek-a-boo, a tickle you telegraph, a sound you build up to.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: they''ll initiate the game. Month 9: they''ll invent variations.'),
  ('do-the-solo-outing-m4', 'bonding_with_baby'::father_activity_category, 4, 'all'::father_activity_relevance, 'Do the Solo Outing', 'Take the baby out alone — a walk, a shop, a relative''s house. No mother present, no backup. It''s the fastest way to build genuine confidence, and it makes clear to everyone including you that you''re a parent, not an assistant.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: longer outings. Month 9: half a day alone together.'),
  ('copy-their-sounds-back-m4', 'bonding_with_baby'::father_activity_category, 4, 'all'::father_activity_relevance, 'Copy Their Sounds Back', 'When they babble, babble the same thing back, then wait. This turn-taking is how conversation is learned, and doing it with you means they''re getting the pattern from two different voices and rhythms.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 7: sequences get longer. Month 10: first words appear.'),
  ('audit-your-own-sleep-m4', 'your_own_wellbeing'::father_activity_category, 4, 'all'::father_activity_relevance, 'Audit Your Own Sleep', 'Track your sleep for a week the way she''s tracking hers. Fathers routinely run a large deficit while assuming theirs doesn''t count because they''re not feeding. Chronic deprivation affects your patience, driving, and work regardless of who''s breastfeeding.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 8: make a structural change if the number is bad.'),
  ('get-your-own-health-checked-m4', 'your_own_wellbeing'::father_activity_category, 4, 'all'::father_activity_relevance, 'Get Your Own Health Checked', 'Blood pressure, weight, bloods. Fathers commonly skip their own health entirely in the first year while attending every paediatric appointment. Book the one you''ve been putting off.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: annual check as a permanent habit.'),
  ('own-the-calendar-m4', 'practical_load'::father_activity_category, 4, 'all'::father_activity_relevance, 'Own the Calendar', 'Every appointment, vaccination, review and reminder lives with you. Not shared — yours. The mental load of remembering is heavier than the doing, and this is the cleanest way to lift a real chunk of it.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: she should be able to genuinely stop tracking dates.'),
  ('add-an-appreciation-m4', 'couple_relationship'::father_activity_category, 4, 'all'::father_activity_relevance, 'Add an Appreciation', 'Add a third element to the nightly five minutes: one specific thing you appreciated about the other today. Observed and specific, not general praise.', 5, '5 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: it becomes automatic.'),
  ('first-date-night-at-home-m4', 'couple_relationship'::father_activity_category, 4, 'all'::father_activity_relevance, 'First Date Night at Home', 'Baby asleep, phones away, table laid, ninety minutes. You don''t need to leave the house to have a date — you need attention and intention. Month four is usually the first point this is realistic.', 90, '90 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 6: weekly. Month 8: first time out of the house.'),
  ('notice-where-your-time-goes-m4', 'becoming_a_father'::father_activity_category, 4, 'all'::father_activity_relevance, 'Notice Where Your Time Goes', 'Track one week honestly: work, commute, baby, chores, your own time, phone. Most fathers find the phone number is large and the baby number is smaller than they assumed. The data is uncomfortable and useful.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 8: track again after making a change.'),
  ('ask-about-her-body-honestly-m5', 'supporting_her_recovery'::father_activity_category, 5, 'all'::father_activity_relevance, 'Ask About Her Body Honestly', 'Six months in, ask specifically: any leaking, pain during sex, back pain, heaviness, a tummy gap that hasn''t closed? These are common, treatable, and almost never volunteered. Asking directly gives permission to answer honestly.', 15, '15 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: ask again. Month 12: full check-in.'),
  ('take-a-night-fully-m5', 'supporting_her_recovery'::father_activity_category, 5, 'all'::father_activity_relevance, 'Take a Night Fully', 'One night a week, she goes to bed early and hears nothing until morning. If bottle-feeding is possible, do the whole night. One genuinely uninterrupted night per week measurably changes mood and functioning.', null, 'Ongoing', 'night'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 8: twice a week if the pattern allows.'),
  ('follow-their-lead-m5', 'bonding_with_baby'::father_activity_category, 5, 'all'::father_activity_relevance, 'Follow Their Lead', 'Fifteen minutes on the floor where you do nothing except respond. No teaching, no directing, no phone. They choose, you follow. This is the single most evidence-backed thing you can do for their development, and it asks less of you than any structured activity.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 8: sessions get longer as their attention grows.'),
  ('be-the-physical-one-m5', 'bonding_with_baby'::father_activity_category, 5, 'all'::father_activity_relevance, 'Be the Physical One', 'Roughhousing — controlled, safe, at their level. Lifting, swinging, rolling, bouncing. Fathers tend to play more physically and it''s genuinely valuable: it builds body confidence, risk judgement, and emotional regulation through excitement and recovery.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 8: they''ll ask for it. Month 12: it becomes a defining part of your relationship.'),
  ('protect-one-evening-m5', 'your_own_wellbeing'::father_activity_category, 5, 'all'::father_activity_relevance, 'Protect One Evening', 'One evening a week that''s yours. Not earned, not negotiated each time. She should have the exact equivalent. Couples who formalise this stop keeping score, and the scorekeeping is what causes the damage.', 180, '180 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: both fixtures, both protected.'),
  ('split-the-load-honestly-m5', 'practical_load'::father_activity_category, 5, 'all'::father_activity_relevance, 'Split the Load Honestly', 'Write down separately what each of you does in a week — including the invisible work of noticing and remembering. Compare. It''s usually uncomfortable. The comparison matters more than the fix, because most imbalance is invisible to the person benefiting from it.', 30, '30 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 9: redo it and see if anything actually changed.'),
  ('weekly-twenty-minutes-m5', 'couple_relationship'::father_activity_category, 5, 'all'::father_activity_relevance, 'Weekly Twenty Minutes', 'A weekly fixture, not a crisis meeting: how are we each doing, what do we need this week, what''s working, what needs to change. Twenty minutes, same slot each week.', 20, '20 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: add a three-month horizon question.'),
  ('plan-something-ahead-m5', 'couple_relationship'::father_activity_category, 5, 'all'::father_activity_relevance, 'Plan Something Ahead', 'Plan one thing three to six months out that you both want — a trip, a visit, a project. Having a future to point at changes how the present feels, and it reframes you as partners in something rather than co-managers of an emergency.', 20, '20 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: make one of them actually happen.'),
  ('talk-to-your-own-father-m5', 'becoming_a_father'::father_activity_category, 5, 'all'::father_activity_relevance, 'Talk to Your Own Father', 'Ask him what it was actually like — what he found hard, what he''d do differently, what he wishes he''d known. Most men have never had this conversation. It tends to be more revealing than expected, and often changes how you read your own childhood.', 60, '60 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: revisit if the first conversation opened something up.'),
  ('support-the-solids-transition-m6', 'supporting_her_recovery'::father_activity_category, 6, 'all'::father_activity_relevance, 'Support the Solids Transition', 'Starting solids is a big shift with real anxiety attached — allergies, choking, whether they''re eating enough. Learn it properly alongside her rather than deferring. Do half the meals. Shared knowledge halves the worry.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 9: you should be equally competent at feeding.'),
  ('notice-the-six-month-wall-m6', 'supporting_her_recovery'::father_activity_category, 6, 'all'::father_activity_relevance, 'Notice the Six-Month Wall', 'Six months is a common low point — the novelty has gone, sleep may still be broken, and the initial support has long evaporated. Watch for it in her and in yourself. Naming it as a known phase rather than a personal failure helps.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: the worst is usually behind you by then.'),
  ('watch-for-the-scar-back-pain-link-m6', 'supporting_her_recovery'::father_activity_category, 6, 'caesarean'::father_activity_relevance, 'Watch for the Scar-Back Pain Link', 'C-section scar tightness pulls the pelvis forward and causes lower back pain that seems completely unrelated to the surgery. If she has persistent back pain, the scar is a likely cause and a physio can treat it directly. Most people never make the connection.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 10: if unresolved, a physio referral is warranted.'),
  ('do-the-solids-mess-m6', 'bonding_with_baby'::father_activity_category, 6, 'all'::father_activity_relevance, 'Do the Solids Mess', 'Own weaning meals — the preparation, the mess, the clean-up. It''s tedious, it''s not glamorous, and it''s exactly the kind of work that quietly defaults to mothers if nobody claims it.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 9: they''ll self-feed and the mess gets worse before better.'),
  ('hide-and-come-back-m6', 'bonding_with_baby'::father_activity_category, 6, 'all'::father_activity_relevance, 'Hide and Come Back', 'They''re working out that things still exist when they can''t see them. Hide behind your hands, a cushion, a door — and reappear. The delight is a prediction being confirmed. It''s also, quietly, how they learn that you leaving doesn''t mean you''re gone.', 10, '10 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: they''ll hide from you. Month 12: they''ll find you deliberately.'),
  ('six-month-self-check-m6', 'your_own_wellbeing'::father_activity_category, 6, 'all'::father_activity_relevance, 'Six-Month Self-Check', 'Check on yourself the way you''d check on her. Withdrawing, irritable, working late to avoid coming home, drinking more, feeling flat? Paternal depression frequently surfaces around now. It''s treatable and asking for help is not a failure of anything.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: annual check as a habit.'),
  ('half-the-mental-load-m6', 'practical_load'::father_activity_category, 6, 'all'::father_activity_relevance, 'Half the Mental Load', 'Not half the tasks — half the noticing. Whether nappies are running low, whether the next size clothes are needed, whether the vaccination is due. If she''s still the one noticing and you''re the one doing, the load isn''t shared.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 9: neither of you should be the default noticer.'),
  ('talk-about-something-else-m6', 'couple_relationship'::father_activity_category, 6, 'all'::father_activity_relevance, 'Talk About Something Else', 'Ten minutes a day about anything other than the baby. A film, a plan, an argument about something trivial. You were two people with opinions before this. That doesn''t maintain itself.', 10, '10 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 9: should feel natural rather than forced.'),
  ('six-month-fatherhood-review-m6', 'becoming_a_father'::father_activity_category, 6, 'all'::father_activity_relevance, 'Six-Month Fatherhood Review', 'What kind of father have you actually been for six months? Not what you intended — what happened. What surprised you, what you''ve avoided, what you want to change in the next six.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: full-year review.'),
  ('back-her-physical-rebuild-m7', 'supporting_her_recovery'::father_activity_category, 7, 'all'::father_activity_relevance, 'Back Her Physical Rebuild', 'She may be returning to running, gym or sport. Cover the time without it being a favour or a negotiation. This is when many women give up on their own recovery because the logistics get too hard to keep arranging.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 10: should be a fixed part of the week.'),
  ('support-the-slower-core-rebuild-m7', 'supporting_her_recovery'::father_activity_category, 7, 'caesarean'::father_activity_relevance, 'Support the Slower Core Rebuild', 'Her abdominal muscles were surgically cut and the nerves disrupted, so core rebuilding is genuinely slower and she may feel behind. Don''t compare her to anyone. Cover the time for physio-led rebuilding rather than encouraging her to push through.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 11: functional strength benchmarks rather than timelines.'),
  ('handle-separation-anxiety-m7', 'bonding_with_baby'::father_activity_category, 7, 'all'::father_activity_relevance, 'Handle Separation Anxiety', 'Around now they may cry when you leave. It''s a developmental milestone, not rejection. Keep goodbyes short, consistent and warm — long drawn-out ones make it worse. Say the same thing every time and always come back when you said.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 10: it eases. Month 12: they wave you off.'),
  ('chase-and-be-chased-m7', 'bonding_with_baby'::father_activity_category, 7, 'all'::father_activity_relevance, 'Chase and Be Chased', 'They''re crawling or close to it. Chase them on all fours, let them escape, chase again. It''s a genuine cardio session for you and a foundational game for them.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 10: they''ll cruise and then run. It only gets harder.'),
  ('rebuild-one-friendship-m7', 'your_own_wellbeing'::father_activity_category, 7, 'all'::father_activity_relevance, 'Rebuild One Friendship', 'Male friendships tend to quietly collapse in the first year of fatherhood and are hard to restart later. Pick one person and make contact. Not a group text — an actual meeting.', 120, '120 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 10: make it regular rather than occasional.'),
  ('first-night-out-together-m7', 'couple_relationship'::father_activity_category, 7, 'all'::father_activity_relevance, 'First Night Out Together', 'Arrange cover and go out for two or three hours as a couple. The first one is often harder emotionally than expected — that difficulty is worth noticing rather than pushing past.', 180, '180 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 10: monthly. It should stop feeling like an operation.'),
  ('ask-about-the-tummy-gap-m8', 'supporting_her_recovery'::father_activity_category, 8, 'all'::father_activity_relevance, 'Ask About the Tummy Gap', 'Around eight months she may check for abdominal separation. If there''s still a gap, or she has back pain or a doming belly during effort, physiotherapy resolves it and time alone often doesn''t. Encourage the appointment and cover the childcare.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: check whether it was actually addressed.'),
  ('build-a-safe-climbing-course-m8', 'bonding_with_baby'::father_activity_category, 8, 'all'::father_activity_relevance, 'Build a Safe Climbing Course', 'Cushions, a low sofa, a mattress on the floor. Let them climb, wobble and fall safely while you spot them. Fathers are often better at tolerating this than mothers, and children need someone who lets them attempt slightly hard things.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 11: they''ll be walking. The course gets more ambitious.'),
  ('baby-proof-properly-m8', 'practical_load'::father_activity_category, 8, 'all'::father_activity_relevance, 'Baby-Proof Properly', 'They''re mobile now. Do a proper sweep on your hands and knees at their height — sockets, corners, cords, stairs, cleaning products, water buckets. Do it before the first accident, not after.', 120, '120 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 10: redo it as they start pulling up and climbing.'),
  ('write-it-down-m8', 'couple_relationship'::father_activity_category, 8, 'all'::father_activity_relevance, 'Write It Down', 'Write her a short note — three sentences, on paper, about what you''ve noticed her do this year. Handwritten is different from spoken. It gets kept and reread on bad days.', 15, '15 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: do it again at the year mark.'),
  ('talk-about-next-year-m8', 'couple_relationship'::father_activity_category, 8, 'all'::father_activity_relevance, 'Talk About Next Year', 'One conversation about twelve months ahead — another child, career moves, where you''ll live, what you want family life to feel like. Being partners in a plan is a different relationship from being partners in a routine.', 30, '30 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: turn it into something written down.'),
  ('nine-month-honest-check-m9', 'supporting_her_recovery'::father_activity_category, 9, 'all'::father_activity_relevance, 'Nine-Month Honest Check', 'Ask her directly: how are you, actually, nine months in? Body, mood, work, us. Nine months is when fatigue is deepest and when everyone assumes you''ve both figured it out. Asking properly at this point matters more than it did at month two.', 30, '30 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: full-year version of the same conversation.'),
  ('be-there-for-first-steps-m9', 'bonding_with_baby'::father_activity_category, 9, 'all'::father_activity_relevance, 'Be There for First Steps', 'First steps usually land between nine and twelve months. Be present for the attempts, not just the milestone — the pulling up, the cruising, the three wobbly seconds. Fathers often miss these to work and then regret it in a way they didn''t expect.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: they''ll walk. The window for this closes quickly.'),
  ('own-bedtime-fully-m9', 'bonding_with_baby'::father_activity_category, 9, 'all'::father_activity_relevance, 'Own Bedtime Fully', 'Take the entire bedtime routine several nights a week — bath, milk, book, settling. It''s the highest-value bonding window of the day and the one most often ceded to mothers by default.', 45, '45 min', 'evening'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 12: they should settle equally well for you.'),
  ('set-a-physical-goal-m9', 'your_own_wellbeing'::father_activity_category, 9, 'all'::father_activity_relevance, 'Set a Physical Goal', 'Pick something with a date on it — a distance, a weight, a game you want to play again. Fathers'' fitness declines quietly across the first year and a goal reverses it more reliably than intention does.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 12: hit it and set the next one.'),
  ('agree-alone-time-properly-m9', 'couple_relationship'::father_activity_category, 9, 'all'::father_activity_relevance, 'Agree Alone Time Properly', 'Sit down and agree explicitly how much individual time each of you gets, when, and how it''s protected. Most couples only have this conversation once someone has already reached breaking point.', 20, '20 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: check whether it actually happened.'),
  ('push-the-physio-question-again-m10', 'supporting_her_recovery'::father_activity_category, 10, 'all'::father_activity_relevance, 'Push the Physio Question Again', 'If anything from her recovery is unresolved — leaking, pain during sex, back pain, the tummy gap — ten months is not too late and it will not fix itself. Book it. Many women have quietly accepted these as permanent by now.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: this should be closed out one way or the other.'),
  ('set-up-the-cruising-circuit-m10', 'bonding_with_baby'::father_activity_category, 10, 'all'::father_activity_relevance, 'Set Up the Cruising Circuit', 'They''re pulling up and cruising along furniture. Arrange a safe loop — sofa, table, chair — and move alongside them encouraging it. Match their energy. This is peak physical development and your enthusiasm genuinely fuels it.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 12: they walk. Then you''re chasing.'),
  ('eat-together-m10', 'bonding_with_baby'::father_activity_category, 10, 'all'::father_activity_relevance, 'Eat Together', 'Sit down and eat the same meal at the same time, at least a few times a week. Family mealtimes are the richest language environment a child gets, and eating together is how food habits and table behaviour actually transfer.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: they''ll copy how you eat, including the parts you''d rather they didn''t.'),
  ('monthly-date-non-negotiable-m10', 'couple_relationship'::father_activity_category, 10, 'all'::father_activity_relevance, 'Monthly Date, Non-Negotiable', 'Two to three hours out, monthly, in the calendar. Not a treat when things are calm — a fixture regardless. The couples who protect this are the ones still functioning at year three.', 180, '180 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: reflect on which of them you actually enjoyed most.'),
  ('let-them-choose-the-book-m11', 'bonding_with_baby'::father_activity_category, 11, 'all'::father_activity_relevance, 'Let Them Choose the Book', 'Keep books at their height and let them pick and bring one to you. The same book forty times is not boredom — it''s how learning works from the inside. Follow their choice without redirecting.', 15, '15 min', 'evening'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: they''ll have clear favourites and so will you.'),
  ('write-to-each-other-m11', 'couple_relationship'::father_activity_category, 11, 'all'::father_activity_relevance, 'Write to Each Other', 'Each write the other a letter: what you appreciated this year as a partner, what you admired as a parent, what you want for the next year. Exchange and read together.', 45, '45 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Keep them. Reread at five years.'),
  ('honest-talk-about-closeness-m11', 'couple_relationship'::father_activity_category, 11, 'all'::father_activity_relevance, 'Honest Talk About Closeness', 'Eleven months in, talk honestly about physical intimacy — what''s returned, what hasn''t, what either of you needs. Many couples let this go unspoken for a full year and then find the distance harder to close than the original problem.', 30, '30 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: name what changed over the year.'),
  ('write-to-your-child-m11', 'becoming_a_father'::father_activity_category, 11, 'all'::father_activity_relevance, 'Write to Your Child', 'Write a letter to your baby about this first year — what you noticed, what surprised you, what you hope for them, what it did to you to become their father. Seal it. Open it on a birthday years from now.', 45, '45 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Repeat annually. It becomes the most valuable thing you write.'),
  ('full-year-recovery-check-m12', 'supporting_her_recovery'::father_activity_category, 12, 'all'::father_activity_relevance, 'Full Year Recovery Check', 'A year on, is anything from her recovery still unresolved? Pelvic floor, tummy gap, scar, pain, mood. A year is a normal timeline for recovery — but ''still recovering'' and ''permanently accepted'' are different things, and the difference is usually one appointment.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Anything unresolved at twelve months should be a referral, not a wait.'),
  ('cover-the-twelve-month-scar-check-m12', 'supporting_her_recovery'::father_activity_category, 12, 'caesarean'::father_activity_relevance, 'Cover the Twelve-Month Scar Check', 'At a year the scar should be flat, pale and mobile. If it''s raised, tight, or there are bands pulling below it, that''s a doctor conversation and treatable — silicone sheeting, physio, or referral. Full maturation takes two years so this is midway, not the deadline.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Continue maintenance through months 18-24 if anything remains.'),
  ('first-birthday-marked-properly-m12', 'bonding_with_baby'::father_activity_category, 12, 'all'::father_activity_relevance, 'First Birthday, Marked Properly', 'Design the first birthday for the adults as much as the child, who won''t remember it. A photo, a meal, something read aloud. You raised a person through their most fragile year. That''s worth marking deliberately.', 180, '180 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Repeat annually. The ritual accumulates meaning.'),
  ('tell-them-the-year-s-story-m12', 'bonding_with_baby'::father_activity_category, 12, 'all'::father_activity_relevance, 'Tell Them the Year''s Story', 'Sit with them and go through the year''s photos, naming people and places and telling the story out loud. They won''t understand yet. But telling your child their own story is a habit worth having, and it starts now.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Do it every year. It becomes a family archive.'),
  ('full-year-self-review-m12', 'your_own_wellbeing'::father_activity_category, 12, 'all'::father_activity_relevance, 'Full Year Self-Review', 'A year in: how are you sleeping, drinking, moving, feeling? What''s declined that you''ve ignored because it seemed less important than everything else? Fix one thing in the next three months.', 30, '30 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Annual habit from here.'),
  ('full-year-relationship-review-m12', 'couple_relationship'::father_activity_category, 12, 'all'::father_activity_relevance, 'Full Year Relationship Review', 'Ninety minutes, no baby, prepared agenda. What was hardest for us this year? What are we proud of? What do we want to protect in year two? The most important conversation of the year for your relationship.', 90, '90 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Repeat annually.'),
  ('keep-three-habits-m12', 'couple_relationship'::father_activity_category, 12, 'all'::father_activity_relevance, 'Keep Three Habits', 'From the whole year — the nightly five minutes, the weekly twenty, the monthly date, the solo evenings — pick the three that actually helped. Write them down. Commit to them for year two rather than rediscovering them from scratch.', 20, '20 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Review quarterly in year two.'),
  ('the-father-you-ve-become-m12', 'becoming_a_father'::father_activity_category, 12, 'all'::father_activity_relevance, 'The Father You''ve Become', 'Reread what you wrote in month three about the father you wanted to be. Compare honestly to the year you actually had. Not to feel bad — to see clearly. Then write the version for year two.', 45, '45 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Repeat annually. The gap narrows if you keep looking at it.'),
  ('decide-what-work-looks-like-now-m12', 'becoming_a_father'::father_activity_category, 12, 'all'::father_activity_relevance, 'Decide What Work Looks Like Now', 'A year in, decide deliberately what role work plays rather than defaulting. Hours, travel, whether you''re home for bedtime, what you''d trade. Fathers who never make this decision consciously usually find it''s been made for them.', 45, '45 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Revisit annually or at any job change.'),
  ('set-up-the-bathroom-m1', 'supporting_her_recovery'::father_activity_category, 1, 'vaginal'::father_activity_relevance, 'Set Up the Bathroom', 'Before she comes home: peri bottle filled and by the toilet, ice packs in the freezer, pads within reach, a soft cushion by every chair she''ll sit in. She''ll be sore in a way that makes fetching things genuinely difficult. Have it ready rather than reactive.', 45, '45 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: restock as things run out without being told.'),
  ('understand-perineal-healing-m1', 'supporting_her_recovery'::father_activity_category, 1, 'vaginal'::father_activity_relevance, 'Understand Perineal Healing', 'She may have tearing or stitches, and sitting, walking and using the toilet will hurt for weeks. Learn what''s normal — swelling, stinging, gradual improvement — and what isn''t: increasing pain after day five, foul smell, fever. She may downplay all of it.', 20, '20 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: know that stitches usually dissolve by now.'),
  ('handle-the-first-toilet-fear-m1', 'supporting_her_recovery'::father_activity_category, 1, 'vaginal'::father_activity_relevance, 'Handle the First Toilet Fear', 'The first bowel movement after a vaginal birth causes real anxiety, and the fear of it causes constipation which then causes straining which hurts. Keep fibre and fluids high, get a stool softener if needed, and treat it as a normal thing to discuss rather than something embarrassing.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 2: should be resolved. If not, mention it to the doctor.'),
  ('know-the-prolapse-signs-m2', 'supporting_her_recovery'::father_activity_category, 2, 'vaginal'::father_activity_relevance, 'Know the Prolapse Signs', 'Heaviness or dragging in the pelvis, a sensation of a bulge, symptoms worse by evening. Common after vaginal delivery, rarely discussed, and very treatable with physiotherapy when caught early. If she mentions any of it, that''s a physio referral not a wait-and-see.', 15, '15 min', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 8: symptoms often reappear as activity increases. Ask again.'),
  ('take-over-standing-tasks-m3', 'supporting_her_recovery'::father_activity_category, 3, 'vaginal'::father_activity_relevance, 'Take Over Standing Tasks', 'Prolonged standing worsens pelvic floor symptoms in the early months. Cooking, washing up, queueing, the school run for older kids — take the standing jobs where you can. It''s a specific, practical thing that directly reduces her symptoms.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'moderate'::father_activity_effort, 'Month 6: less critical as the pelvic floor strengthens.'),
  ('ask-about-intercourse-pain-m6', 'supporting_her_recovery'::father_activity_category, 6, 'vaginal'::father_activity_relevance, 'Ask About Intercourse Pain', 'If sex is painful, that is not something she should be enduring quietly or waiting out. It usually means scar tightness or an overactive pelvic floor, both of which physiotherapy treats effectively. Raise it kindly and make clear the goal is her comfort, not your access.', 20, '20 min', 'evening'::father_activity_time_of_day, 'no'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 10: if unresolved, this should be a priority referral.'),
  ('cover-the-impact-test-window-m9', 'supporting_her_recovery'::father_activity_category, 9, 'vaginal'::father_activity_relevance, 'Cover the Impact Test Window', 'Before she returns to running, she needs to test for leaking under impact. Cover the childcare so she can do it properly and see a physio if it fails. Returning to running too early causes problems that take much longer to fix than waiting would have.', null, 'Ongoing', 'anytime'::father_activity_time_of_day, 'yes'::father_activity_with_baby, 'gentle'::father_activity_effort, 'Month 12: she should be running comfortably or under treatment.');
